#!/usr/bin/env python3
"""Merge two PDF files into a single output PDF (task-scoped helper)."""
import sys

from pypdf import PdfReader, PdfWriter


def main() -> int:
    if len(sys.argv) != 4:
        print("usage: merge_pdfs.py <input1.pdf> <input2.pdf> <output.pdf>", file=sys.stderr)
        return 2

    input1, input2, output = sys.argv[1], sys.argv[2], sys.argv[3]

    writer = PdfWriter()
    for pdf_file in (input1, input2):
        reader = PdfReader(pdf_file)
        for page in reader.pages:
            writer.add_page(page)

    with open(output, "wb") as out:
        writer.write(out)

    print(f"Merged {input1} + {input2} -> {output} ({len(writer.pages)} pages total)")
    return 0


if __name__ == "__main__":
    sys.exit(main())

